Selector sel = Selector.open();
server.configureBlocking(false).register(sel, SelectionKey.OP_ACCEPT, acceptHandler);

while (running) {
    sel.select();                                  // demultiplex readiness
    for (SelectionKey k : sel.selectedKeys()) {    // ready set
        if (k.isValid()) ((Runnable) k.attachment()).run();   // dispatch the handler
    }
    sel.selectedKeys().clear();                    // consume, or select() returns immediately forever
}

