EventLoopGroup boss = new NioEventLoopGroup(1);
EventLoopGroup workers = new NioEventLoopGroup();          // one selector per loop thread
ServerBootstrap b = new ServerBootstrap()
    .group(boss, workers)
    .channel(NioServerSocketChannel.class)
    .childHandler(new ChannelInitializer<SocketChannel>() {
        protected void initChannel(SocketChannel ch) { ch.pipeline().addLast(new EchoHandler()); }
    });
b.bind(8080).sync().channel().closeFuture().sync();        // the loops dispatch; handlers react
